package net.civeira.phylax.features.document.template.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.document.template.domain.Template;
import net.civeira.phylax.features.document.template.domain.valueobject.ThemeVO;

@RequiredArgsConstructor
public class ThemeValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ThemeVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getTheme() {
    return value.flatMap(ThemeVO::getTheme);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ThemeVO> getThemeValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ThemeVO readTheme(final Optional<Template> original, final ConstraintFailList fails) {
    return value.orElse(original.map(Template::getThemeValue).orElseGet(ThemeVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param theme
   * @return
   */
  public T theme(ThemeVO theme) {
    this.value = Optional.of(theme);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param theme
   * @return
   */
  public T theme(Optional<ThemeVO> theme) {
    this.value = theme;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param theme
   * @return
   */
  public T theme(String theme) {
    this.value = Optional.of(ThemeVO.from(theme));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T themeNull() {
    this.value = Optional.empty();
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetTheme() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetThemeIfMatches(final String field) {
    if ("theme".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
